const merged = $input.first().json;
const normalized = $('Normalizar Entrada').first().json;

function finiteNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

function extractUsage(...roots) {
  for (const root of roots) {
    if (!root || typeof root !== 'object') continue;
    const candidates = [
      root.tokenUsage,
      root.providerUsage,
      root.usage_metadata,
      root.usageMetadata,
      root.response_metadata?.usage_metadata,
      root.responseMetadata?.usageMetadata,
      root.llmOutput?.tokenUsage,
    ].filter(Boolean);
    for (const usage of candidates) {
      const input = finiteNumber(
        usage.promptTokens ??
        usage.inputTokens ??
        usage.input_tokens ??
        usage.promptTokenCount
      );
      const output = finiteNumber(
        usage.completionTokens ??
        usage.outputTokens ??
        usage.output_tokens ??
        usage.candidatesTokenCount
      );
      const total = finiteNumber(
        usage.totalTokens ??
        usage.total_tokens ??
        usage.totalTokenCount
      );
      if (input !== undefined || output !== undefined || total !== undefined) {
        return {
          input: input ?? -1,
          output: output ?? -1,
          total: total ?? (
            input !== undefined && output !== undefined ? input + output : -1
          ),
          available: true,
        };
      }
    }
  }
  return { input: -1, output: -1, total: -1, available: false };
}

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

const baselineOutput = String(merged.baseline_output ?? '');
const optimizedOutput = String(merged.optimized_output ?? '');
const baselineTelemetry = merged.modelTelemetry?.baseline || {};
const optimizedTelemetry = merged.modelTelemetry?.optimized || {};
const baselineUsage = extractUsage(baselineTelemetry);
const optimizedUsage = extractUsage(optimizedTelemetry);
const optimization = optimizedTelemetry.optimization || {};
const realUsageAvailable = baselineUsage.available && optimizedUsage.available;
const savedInputTokens = realUsageAvailable
  ? baselineUsage.input - optimizedUsage.input
  : -1;
const savingsPercent = realUsageAvailable && baselineUsage.input > 0
  ? Number(((savedInputTokens / baselineUsage.input) * 100).toFixed(2))
  : -1;
const sameResponse =
  normalizeText(baselineOutput) === normalizeText(optimizedOutput);
const qualityCheckRan = String(normalized.chatInput)
  .trim()
  .toUpperCase()
  .startsWith('COMPARAR:');
const expectedFacts = [
  'atlas',
  'curitiba/pr',
  'fran-4271',
  'r$ 850.000,00',
  '05/08/2026',
  '14:30',
];
const baselineNormalized = normalizeText(baselineOutput);
const optimizedNormalized = normalizeText(optimizedOutput);
const factsPreserved = qualityCheckRan
  ? expectedFacts.every((fact) => {
      const normalizedFact = normalizeText(fact);
      return baselineNormalized.includes(normalizedFact) &&
        optimizedNormalized.includes(normalizedFact);
    })
  : false;

return [{
  json: {
    session_id: normalized.sessionId,
    execution_id: String($execution.id),
    created_at: new Date().toISOString(),
    chat_input: normalized.chatInput,
    baseline_output: baselineOutput,
    optimized_output: optimizedOutput,
    baseline_input_tokens: baselineUsage.input,
    baseline_output_tokens: baselineUsage.output,
    optimized_input_tokens: optimizedUsage.input,
    optimized_output_tokens: optimizedUsage.output,
    saved_input_tokens: savedInputTokens,
    savings_percent: savingsPercent,
    messages_before: finiteNumber(optimization.messagesBefore) ?? -1,
    messages_after: finiteNumber(optimization.messagesAfter) ?? -1,
    estimated_before: finiteNumber(optimization.tokensBeforeEstimated) ?? -1,
    estimated_after: finiteNumber(optimization.tokensAfterEstimated) ?? -1,
    same_response: sameResponse,
    quality_check_ran: qualityCheckRan,
    facts_preserved: factsPreserved,
    measurement_type: realUsageAvailable ? 'real' : 'indisponivel',
    fallback: Boolean(optimization.bypassReason),
    bypass_reason: String(optimization.bypassReason ?? ''),
  },
}];

const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && Object.keys(row).length > 0);
const current = $('Comparar e Consolidar').first().json;

function displayTokens(value) {
  const number = Number(value);
  return Number.isFinite(number) && number >= 0
    ? number.toLocaleString('pt-BR')
    : 'indisponível';
}

function displayPercent(value) {
  const number = Number(value);
  return Number.isFinite(number) && number >= 0
    ? number.toLocaleString('pt-BR', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }) + '%'
    : 'indisponível';
}

const measuredRows = rows.filter((row) =>
  Number(row.baseline_input_tokens) >= 0 &&
  Number(row.optimized_input_tokens) >= 0
);
const cumulativeBaseline = measuredRows.reduce(
  (sum, row) => sum + Number(row.baseline_input_tokens),
  0
);
const cumulativeOptimized = measuredRows.reduce(
  (sum, row) => sum + Number(row.optimized_input_tokens),
  0
);
const cumulativeSaved = cumulativeBaseline - cumulativeOptimized;
const cumulativePercent = cumulativeBaseline > 0
  ? (cumulativeSaved / cumulativeBaseline) * 100
  : -1;
const quality = current.quality_check_ran
  ? (current.facts_preserved ? '100% dos fatos do roteiro preservados' : 'FALHOU — fato ausente')
  : 'não executada neste turno';
const messageCount = Number(current.messages_before) >= 0
  ? displayTokens(current.messages_before) + ' → ' + displayTokens(current.messages_after)
  : 'indisponível';

const output = [
  '## BASELINE',
  current.baseline_output,
  '',
  '**Input real:** ' + displayTokens(current.baseline_input_tokens),
  '**Output real:** ' + displayTokens(current.baseline_output_tokens),
  '',
  '## OTIMIZADO',
  current.optimized_output,
  '',
  '**Input real:** ' + displayTokens(current.optimized_input_tokens),
  '**Output real:** ' + displayTokens(current.optimized_output_tokens),
  '**Mensagens antes → depois:** ' + messageCount,
  '',
  '## RESULTADO',
  '**Economia do turno:** ' + displayTokens(current.saved_input_tokens) +
    ' tokens (' + displayPercent(current.savings_percent) + ')',
  '**Economia acumulada:** ' + displayTokens(cumulativeSaved) +
    ' tokens (' + displayPercent(cumulativePercent) + ')',
  '**Turnos medidos:** ' + measuredRows.length,
  '**Respostas idênticas:** ' + (current.same_response ? 'sim' : 'não'),
  '**Qualidade:** ' + quality,
  '**Medição:** ' + current.measurement_type,
  '**Fallback/bypass:** ' + (current.fallback
    ? 'sim — ' + current.bypass_reason
    : 'não'),
].join('\n');

return [{
  json: {
    output,
    session_id: current.session_id,
    execution_id: current.execution_id,
    baseline_input_tokens: current.baseline_input_tokens,
    optimized_input_tokens: current.optimized_input_tokens,
    saved_input_tokens: current.saved_input_tokens,
    savings_percent: current.savings_percent,
    cumulative_saved_tokens: cumulativeSaved,
    cumulative_savings_percent: cumulativePercent,
    facts_preserved: current.facts_preserved,
    same_response: current.same_response,
    measurement_type: current.measurement_type,
  },
}];
